'use strict';
const $ = id => document.getElementById(id);
const motors = Array.from({length:6}, (_,i) => ({name:`AK45-${i+1}`,online:i<2,current:i===0?10.2:i===1?-5.1:0,target:i===0?10.2:i===1?-5.1:0,draft:i===0?12:0,status:'Idle'}));
let selected=0, stopped=false;
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('toasts').append(el);setTimeout(()=>el.remove(),4500);}
function drawList(){ $('motor-list').replaceChildren();motors.forEach((m,i)=>{const b=document.createElement('button');b.type='button';b.className=`motor ${i===selected?'active':''} ${m.online?'':'offline'}`;b.setAttribute('aria-pressed',String(i===selected));b.setAttribute('aria-label',`${m.name}, ${m.online?'Online':'Offline'}`);b.innerHTML=`<span class="motor-icon">⬡</span><span class="motor-info"><strong>${m.name}</strong><small><i class="dot ${m.online?'green':'muted'}"></i>${m.online?'Online':'Offline'}</small></span><span class="motor-angle">${m.online?m.current.toFixed(1)+'°':'—'}</span>`;b.onclick=()=>{selected=i;syncDraft();render();if(!m.online)toast('Motor disconnected',true);};$('motor-list').append(b);});}
function syncDraft(){const m=motors[selected];$('target').value=m.draft.toFixed(1);$('slider').value=m.draft;$('input-error').textContent='';$('target').removeAttribute('aria-invalid');updateSlider();}
function updateSlider(){const v=Number($('slider').value);$('slider').style.background=`linear-gradient(to right,#639fff ${(v+15)/30*100}%,#2a3749 ${(v+15)/30*100}%)`;}
function render(){const m=motors[selected];drawList();$('selected-name').textContent=m.name;$('status-name').textContent=m.name;$('current').textContent=m.online?m.current.toFixed(1):'—';$('selected-status').textContent=m.online?'● Online':'● Offline';$('selected-status').className='badge'+(m.online?' green-badge':'');$('metric-current').innerHTML=m.online?`${m.current.toFixed(1)}<small>°</small>`:'—';$('metric-target').innerHTML=m.online?`${m.target.toFixed(1)}<small>°</small>`:'—';$('metric-difference').innerHTML=m.online?`${Math.abs(m.target-m.current).toFixed(1)}<small>°</small>`:'—';const status=!m.online?'Disconnected':stopped?'Stopped':m.status;$('motion').textContent='● '+status;$('motion').style.color=status==='Reached'?'#68dcb0':status==='Moving'?'#7db1ff':status==='Stopped'?'#ff9097':'#a4b0bf';$('status-description').textContent=status==='Moving'?'Moving toward target position':status==='Reached'?'Target position reached':status==='Disconnected'?'Connect this motor to enable control':stopped?'Control disabled by emergency stop':'Ready for your next command';['target','slider','minus','plus','send'].forEach(id=>$(id).disabled=stopped||!m.online);$('emergency').hidden=!stopped;$('connection').textContent=stopped?'Warning':'Connected';$('connection').previousElementSibling.style.background=stopped?'#f59e0b':'#48d6a0';$('dial-arc').style.opacity=m.online?'1':'.15';$('dial-arc').setAttribute('stroke-dasharray',`${m.online?(m.current+15)/30*405:0} 450`);}
function validate(){const raw=$('target').value;const v=Number(raw);const valid=raw.trim()!==''&&Number.isFinite(v)&&v>=-15&&v<=15;$('input-error').textContent=valid?'':'−15.0°부터 +15.0° 사이의 각도를 입력하세요.';$('target').setAttribute('aria-invalid',String(!valid));return valid;}
$('target').addEventListener('input',()=>{if(validate()){motors[selected].draft=Number($('target').value);$('slider').value=motors[selected].draft;updateSlider();}});
$('target').addEventListener('change',()=>{if(validate())syncDraft();});
$('slider').addEventListener('input',()=>{motors[selected].draft=Number($('slider').value);syncDraft();});
function step(delta){const v=Number($('target').value);motors[selected].draft=Math.round(Math.min(15,Math.max(-15,(Number.isFinite(v)?v:0)+delta))*10)/10;syncDraft();}
$('minus').onclick=()=>step(-.1);$('plus').onclick=()=>step(.1);
$('command-form').addEventListener('submit',event=>{event.preventDefault();const m=motors[selected];if(stopped)return;if(!m.online){toast('Motor disconnected',true);return;}if(!validate()){toast('Angle exceeds allowed range',true);return;}m.target=Math.round(Number($('target').value)*10)/10;m.draft=m.target;m.status=Math.abs(m.current-m.target)<.05?'Reached':'Moving';syncDraft();render();toast(`Command sent successfully · ${m.name} → ${m.target.toFixed(1)}°`);});
$('stop').onclick=()=>{stopped=true;motors.forEach(m=>{if(m.online)m.status='Idle';});render();toast('Emergency stop requested · simulation paused',true);};
$('reset').onclick=()=>{stopped=false;motors.forEach(m=>{m.status='Idle';});render();toast('Control reset · ready for commands');};
setInterval(()=>{if(stopped)return;let changed=false;motors.forEach(m=>{if(m.status!=='Moving')return;const diff=m.target-m.current;m.current=Math.round((Math.abs(diff)<=.2?m.target:m.current+Math.sign(diff)*.2)*10)/10;if(m.current===m.target)m.status='Reached';changed=true;});if(changed)render();},100);
syncDraft();render();
